entries[14314] = { ["name"] = "Sprengfalle", ["text"] = "Sofort\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Ranged attack power * 0.1 + 139) bis (Ranged attack power * 0.1 + 187) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie 20 sec lang insgesamt 240 zusätzlichen Feuerschaden verursacht. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14315] = { ["name"] = "Sprengfalle", ["text"] = "Sofort\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Ranged attack power * 0.1 + 201) bis (Ranged attack power * 0.1 + 257) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie 20 sec lang insgesamt 330 zusätzlichen Feuerschaden verursacht. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14316] = { ["name"] = "Sprengfalle", ["text"] = "19% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Ranged attack power * 0.1 + 139) bis (Ranged attack power * 0.1 + 187) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen zusätzlich im Verlauf von 20 sec insgesamt (24 * 10 + Ranged attack power) Feuerschaden zufügt. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14317] = { ["name"] = "Sprengfalle", ["text"] = "19% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Ranged attack power * 0.1 + 201) bis (Ranged attack power * 0.1 + 257) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen zusätzlich im Verlauf von 20 sec insgesamt (33 * 10 + Ranged attack power) Feuerschaden zufügt. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
