entries[14326] = { ["name"] = "Wildtier ängstigen", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 15 sec lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
