entries[14516] = { ["name"] = "Schlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nSchlägt einen Feind und fügt erhöhten Nahkampfschaden zu." }
entries[14517] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 27 Schaden bei einem Feind und erhöht seinen erlittenen Heiligschaden um 10 pro Kreuzfahrerstoß. Kann bis zu 5-mal angewendet werden. Hält 30 sec lang an." }
entries[14518] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 50 Schaden bei einem Feind und erhöht seinen erlittenen Heiligschaden um 20 pro Kreuzfahrerstoß. Kann bis zu 5-mal angewendet werden. Hält 30 sec lang an." }
entries[14520] = { ["name"] = "Mentale Beweglichkeit", ["text"] = "Verringert die Manakosten Eurer Sofortzauber um 4%." }
entries[14521] = { ["name"] = "Meditation", ["text"] = "Ermöglicht, dass 17% Eurer Manaregeneration während des Zauberwirkens weiterläuft." }
entries[14522] = { ["name"] = "Unbezwingbarer Wille", ["text"] = "Verringert die Dauer auf Euch wirkender Betäubungs-, Furcht- und Stilleeffekte um weitere 6%." }
entries[14523] = { ["name"] = "Schweigsame Entschlossenheit", ["text"] = "Verringert die von Euren Heilig- und Disziplinzaubern verursachte Bedrohung um 7% und die Chance, dass sowohl Eure hilfreichen Zauber als auch Effekte, die Schaden im Laufe der Zeit verursachen, gebannt werden, um 10%." }
entries[14524] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 15%." }
