entries[14528] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 25%." }
entries[14530] = { ["name"] = "Tempo", ["text"] = "Sofort\nErhöht das Lauftempo 10 sec lang um 40%." }
entries[14531] = { ["name"] = "Märtyrertum", ["text"] = "Gewährt Euch eine Chance von 50%, den Effekt 'Fokussiertes Zauberwirken' zu erhalten, der 6 sec lang anhält, nachdem Ihr Opfer eines kritischen Nahkampf- oder Distanzangriffs wart. Der Effekt 'Fokussiertes Zauberwirken' verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Priesterzaubern und die Dauer von Unterbrechungseffekten um 10%.\n(Procchance: 50%)" }
entries[14532] = { ["name"] = "Krabblergift", ["text"] = "Wirken in 2 sek.\nErhöht den erlittenen körperlichen Schaden von in der Nähe befindlichen Feinden 5 min lang um 30%." }
entries[14533] = { ["name"] = "Abtrennung", ["text"] = "Sofort\nErhöht 5 min lang den von in der Nähe befindlichen Feinden erlittenen Feuer-, Frost- und Arkanschaden um 50%." }
entries[14534] = { ["name"] = "Stachelstich", ["text"] = "Sofort\nErhöht die Zeit zwischen Angriffen in der Nähe befindlicher Feinde 5 min lang um 54%." }
entries[14535] = { ["name"] = "Baggererkrankung", ["text"] = "Sofort\nVerringert alle Attribute von in der Nähe befindlichen Feinden 5 min lang um 25%." }
entries[14537] = { ["name"] = "Sechsdämonentasche", ["text"] = "30 Meter Reichweite\nSofort\nÜberzieht den Feind mit der Macht des Windes, des Feuers und all solchen Dingen!" }
entries[14538] = { ["name"] = "Auraschock", ["text"] = "Sofort\nVerringert das Zaubertempo von in der Nähe befindlichen Feinden 5 min lang um 35%." }
entries[14539] = { ["name"] = "Eitriges Enzym", ["text"] = "Sofort\nErhöht den erlittenen Naturschaden von in der Nähe befindlichen Feinden um 50% und erhöht den von ihnen erlittenen Schattenschaden um 50%. Hält 5 min lang an." }
